#!/usr/bin/env node
// Sprint 5 (S5.7) integration verification: data packs -> pack-loader ->
// portfolio engine, compared against Python-golden envelopes generated by
// scripts/generate_portfolio_fixtures.py.
//
// Plain Node >= 18, no npm install, no network. Covers:
//   (a) QQQ buy-and-hold from real pack-derived inputs matching the Python
//       golden exactly;
//   (b) QQQ buy + partial sell realised/unrealised P/L matching the golden;
//   (c) shuffle-invariance: transaction order never changes the envelope;
//   plus the synthetic ledger cases (multiple currencies, dividends,
//   cash-only rows, zero holdings) and the missing as-of price error golden.
//   A compact round-trip check of frontend/ledger-store.js is included.
//
// Exit status: 0 when every check passes, 1 otherwise.

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { analyzePortfolio, AnalysisDataError, Decimal, EngineValueError } from './index.js';
import { createPackLoader } from './pack-loader.js';
import { payloadToEngineArgs, validateRequestPayload } from './worker.js';
import { createLedgerStore, createMemoryDriver } from '../ledger-store.js';

const FIXTURES_DIR = new URL('./parity/fixtures/portfolio-fixtures/', import.meta.url);
const FRONTEND_ROOT = fileURLToPath(new URL('../', import.meta.url));
const FIXTURE_FILES = [
  'portfolio-pack-qqq-buy-hold.json',
  'portfolio-pack-qqq-partial-sell.json',
  'portfolio-synthetic-mixed-currency.json',
  'portfolio-synthetic-dividends.json',
  'portfolio-synthetic-cash-only.json',
  'portfolio-synthetic-zero-holding.json',
  'portfolio-synthetic-missing-as-of-price.json',
];

const DECIMAL_RE = /^-?\d+(\.\d+)?([eE][+-]?\d+)?$/;
const ERROR_TYPE_MAP = { AnalysisDataError, ValueError: EngineValueError };

function fsFetcher(url) {
  const path = url.startsWith('file://') ? fileURLToPath(url) : url;
  try {
    const text = readFileSync(path, 'utf8');
    return { ok: true, status: 200, json: async () => JSON.parse(text) };
  } catch (error) {
    return { ok: false, status: error.code === 'ENOENT' ? 404 : 500, json: async () => ({}) };
  }
}

const packLoader = createPackLoader({ baseUrl: FRONTEND_ROOT, fetcher: fsFetcher });

function serializeEnvelope(value) {
  return JSON.parse(JSON.stringify(value, (key, item) => (item instanceof Decimal ? item.toString() : item)));
}

function compareValues(actual, expected, path, errors) {
  if (Array.isArray(expected)) {
    if (!Array.isArray(actual) || actual.length !== expected.length) {
      errors.push({ path, expected: `array[${expected.length}]`, actual: describe(actual) });
      return;
    }
    for (let i = 0; i < expected.length; i += 1) compareValues(actual[i], expected[i], `${path}[${i}]`, errors);
    return;
  }
  if (expected !== null && typeof expected === 'object') {
    if (actual === null || typeof actual !== 'object' || Array.isArray(actual)) {
      errors.push({ path, expected: 'object', actual: describe(actual) });
      return;
    }
    const expectedKeys = Object.keys(expected).sort();
    const actualKeys = Object.keys(actual).sort();
    if (JSON.stringify(actualKeys) !== JSON.stringify(expectedKeys)) {
      errors.push({ path, expected: `{${expectedKeys.join(',')}}`, actual: `{${actualKeys.join(',')}}` });
      return;
    }
    for (const key of expectedKeys) compareValues(actual[key], expected[key], `${path}.${key}`, errors);
    return;
  }
  if (typeof expected === 'string' && DECIMAL_RE.test(expected) && DECIMAL_RE.test(actual)) {
    if (!new Decimal(actual).eq(new Decimal(expected))) errors.push({ path, expected, actual });
    return;
  }
  if (actual !== expected) errors.push({ path, expected: JSON.stringify(expected), actual: JSON.stringify(actual) });
}

function describe(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'array';
  return typeof value;
}

function compareError(actualError, expectedError) {
  const errors = [];
  const ExpectedClass = ERROR_TYPE_MAP[expectedError.type];
  if (!ExpectedClass || !(actualError instanceof ExpectedClass)) {
    errors.push({ path: 'error.type', expected: expectedError.type, actual: actualError?.name ?? 'no error thrown' });
  }
  if (String(actualError?.message) !== expectedError.message) {
    errors.push({ path: 'error.message', expected: expectedError.message, actual: String(actualError?.message) });
  }
  return errors;
}

function securitiesMap(fixture) {
  return Object.fromEntries(fixture.input_rows.security.map((row) => [row.security_id, row]));
}

function syntheticPayload(fixture) {
  return {
    as_of: fixture.input_rows.request.as_of,
    transactions: fixture.input_rows.request.transactions,
    securities: securitiesMap(fixture),
    prices: fixture.input_rows.prices,
    fx_rates: fixture.input_rows.fx_rates,
  };
}

async function packDerivedPayload(fixture) {
  const { security_ticker: ticker, input_start: start, input_end: end } = fixture.meta;
  const entry = await packLoader.findSecurity({ ticker });
  if (!entry) throw new Error(`manifest has no entry for ${ticker}`);
  const inputs = await packLoader.loadSecurityInputs(entry, start, end);
  if (inputs.support.status !== 'fully_supported') {
    throw new Error(`${ticker} range ${start}..${end} not fully supported: ${inputs.support.reason}`);
  }
  const securities = { [inputs.security.security_id]: inputs.security };
  return {
    as_of: fixture.input_rows.request.as_of,
    transactions: fixture.input_rows.request.transactions,
    securities,
    prices: inputs.prices,
    fx_rates: inputs.fxRates,
  };
}

function runPortfolio(payload) {
  return analyzePortfolio(payloadToEngineArgs('portfolio', payload));
}

function permuted(transactions, mode) {
  if (mode === 'reverse') return [...transactions].reverse();
  const pivot = Math.floor(transactions.length / 2);
  return [...transactions.slice(pivot), ...transactions.slice(0, pivot)];
}

async function runFixtures() {
  let passed = 0;
  let total = 0;
  const failures = [];

  for (const name of FIXTURE_FILES) {
    total += 1;
    const fixture = JSON.parse(readFileSync(new URL(name, FIXTURES_DIR), 'utf8'));
    const errors = [];
    try {
      const payload = fixture.meta.pack_derived
        ? await packDerivedPayload(fixture)
        : syntheticPayload(fixture);
      const problems = validateRequestPayload('portfolio', payload);
      if (problems.length) throw new Error(`payload rejected by protocol validation: ${problems.join('; ')}`);

      if (fixture.golden_envelope.error) {
        let thrown = null;
        try {
          runPortfolio(payload);
        } catch (error) {
          thrown = error;
        }
        errors.push(...compareError(thrown, fixture.golden_envelope.error));
      } else {
        const envelope = serializeEnvelope(runPortfolio(payload));
        compareValues(envelope, fixture.golden_envelope, fixture.name, errors);
        // (c) shuffle-invariance: order in, sorted (date, id) order out.
        const transactions = payload.transactions;
        for (const mode of ['reverse', 'rotate']) {
          const shuffledEnvelope = serializeEnvelope(
            runPortfolio({ ...payload, transactions: permuted(transactions, mode).map((row) => ({ ...row })) }),
          );
          compareValues(shuffledEnvelope, envelope, `${fixture.name}.shuffle-${mode}`, errors);
        }
      }
    } catch (error) {
      errors.push({ path: '(run)', expected: 'fixture passes', actual: `${error.name}: ${error.message}` });
    }
    if (errors.length === 0) {
      passed += 1;
      console.log(`  ok   ${fixture.name}`);
    } else {
      failures.push({ name: fixture.name, errors });
    }
  }

  for (const { name, errors } of failures) {
    console.log(`\nFAIL ${name}`);
    for (const error of errors) console.log(`  ${error.path}\n    expected: ${error.expected}\n    actual:   ${error.actual}`);
  }
  return { passed, total };
}

async function runLedgerStoreChecks() {
  let passed = 0;
  let total = 0;
  const check = (name, condition) => {
    total += 1;
    if (condition) {
      passed += 1;
      console.log(`  ok   ledger-store ${name}`);
    } else {
      console.log(`  FAIL ledger-store ${name}`);
    }
  };
  const store = createLedgerStore(createMemoryDriver());
  const rows = [
    { transaction_type: 'BUY', security_id: 's1', transaction_date: '2024-01-02', quantity: '10', cash_amount: '4000', currency: 'USD', fees: '0' },
    { transaction_type: 'CASH_DEPOSIT', security_id: null, transaction_date: '2024-01-02', quantity: '0', cash_amount: '1000', currency: 'SGD', fees: '0' },
  ];
  check('save+load round-trip', JSON.stringify(await store.save(rows)) === JSON.stringify(rows));
  check('load returns saved rows', JSON.stringify(await store.load()) === JSON.stringify(rows));
  const exported = JSON.parse(await store.exportJson());
  check('exportJson envelope', exported.schema === 'sg-invest-ledger' && exported.rows.length === 2);
  await store.clear();
  check('clear empties the ledger', (await store.load()).length === 0);
  await store.importJson(await store.exportJson().then(() => JSON.stringify(exported)));
  check('importJson restores rows', JSON.stringify(await store.load()) === JSON.stringify(rows));
  let rejected = false;
  try {
    await store.importJson('not-json');
  } catch {
    rejected = true;
  }
  check('import rejects invalid JSON', rejected);
  let badRow = false;
  try {
    await store.save([{ transaction_type: 'LIQUIDATE' }]);
  } catch {
    badRow = true;
  }
  check('save rejects unknown transaction type', badRow);
  return { passed, total };
}

async function main() {
  console.log('== Portfolio packs integration (pack-loader + engine vs Python goldens) ==');
  const fixtures = await runFixtures();
  console.log('== Ledger store round-trip (memory driver) ==');
  const ledger = await runLedgerStoreChecks();
  const passed = fixtures.passed + ledger.passed;
  const total = fixtures.total + ledger.total;
  console.log(`\n==== PORTFOLIO PACKS INTEGRATION: ${passed}/${total} PASS ====`);
  process.exitCode = passed === total ? 0 : 1;
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
